// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        value = bound(value, 0, address(this).balance);
        uint256 balanceBefore = address(c).balance;
        c.sendMoney(target, value, data);
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter <= balanceBefore + value, "Balance increased more than value sent");
    }
}

